import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    # Read ChemForces elements
    element_income = {}
    for _ in range(n):
        a = int(next(it))
        x = int(next(it))
        element_income[a] = x

    m = int(next(it))

    # Read TopChemist elements and merge
    for _ in range(m):
        b = int(next(it))
        y = int(next(it))
        if b in element_income:
            element_income[b] = max(element_income[b], y)
        else:
            element_income[b] = y

    # Sum all incomes
    total = sum(element_income.values())
    print(total)

if __name__ == "__main__":
    main()
"}

