{"code": "
n, r = map(int, input().split())
house = list(map(int, input().split()))

# Check if there are no heaters
if sum(house) == 0:
    print(-1)
else:
    count = 0
    i = 0  # current position to cover (0-indexed)
    while i < n:
        # Find the farthest heater that can cover position i
        farthest = -1
        for j in range(n):
            if house[j] == 1 and j - r + 1 <= i <= j + r - 1:
                farthest = j

        if farthest == -1:
            print(-1)
            break

        count += 1
        i = farthest + r  # skip all positions covered by this heater
    else:
        print(count)
"}

