{"code": "
n, k = map(int, input().split())
a = list(map(int, input().split()))

# Try each tree as the pivot
min_ops = n  # Worst case: adjust all trees
best_config = None

for pivot_idx in range(n):
    # Set the target height for the pivot tree to its current height
    pivot_val = a[pivot_idx]
    target = [0] * n
    target[pivot_idx] = pivot_val

    # Compute target heights for all other trees
    for i in range(n):
        if i != pivot_idx:
            target[i] = pivot_val + (i - pivot_idx) * k

    # Count how many trees need adjustment
    adjust_count = 0
    for i in range(n):
        if a[i] != target[i]:
            adjust_count += 1

    # Check if this is the best configuration
    if adjust_count < min_ops:
        min_ops = adjust_count
        best_config = target

# Output the result
print(min_ops)

# Print the operations
for i in range(n):
    if a[i] != best_config[i]:
        if a[i] < best_config[i]:
            print(f"+ {i+1} {best_config[i] - a[i]}")
        else:
            print(f"- {i+1} {a[i] - best_config[i]}")
"}

