        max_digit = min(i, 2 * n - i)

        # Generate the pattern: 0 1 2 ... max_digit ... 2 1 0
        digits = []
        for d in range(max_digit + 1):
            digits.append(str(d))
        for d in range(max_digit - 1, -1, -1):
