def is_tolerable(s):
    """Check if string s is tolerable (no palindromes of length 2 or 3)."""
    # Check for palindromes of length 2
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            return False

    # Check for palindromes of length 3
    for i in range(len(s) - 2):
        if s[i] == s[i + 2]:
            return False

    return True

def next_tolerable(n, p, s):
    """Find the next tolerable string or return "NO"."""
    # Try to increment each character from right to left
    for i in range(n - 1, -1, -1):
        # Get the current character and its position
        current_char = s[i]

        # Try each character larger than current_char
        for c in range(ord(current_char) + 1, ord('a') + p):
            # Create the new string
            new_s = s[:i] + chr(c) + s[i+1:]

            # Check if this new string is tolerable
            if is_tolerable(new_s):
                return new_s

    # No tolerable string found
    return "NO"

# Read input
n, p = map(int, input().split())
original_s = input().strip()

# Find and print the next tolerable string
print(next_tolerable(n, p, original_s))
