import sys
import math

def gcd(x, y):
    """Calculate GCD of two numbers"""
    while y:
        x, y = y, x % y
    return x

def is_coprime_with_all(x, coprimes):
    """Check if x is coprime with all elements in coprimes"""
    for c in coprimes:
        if gcd(x, c) != 1:
            return False
    return True

def find_next_coprime(start, coprimes):
    """Find the smallest number ≥ start that is coprime with all in coprimes"""
    if not coprimes:
        return start

    # Try values from start upwards
    for v in range(start, 10**5 + 1):
        if is_coprime_with_all(v, coprimes):
            return v

    # If none found in range, we need a prime that's coprime with all
    # Find the smallest prime > max(coprimes) that's not in coprimes
    max_val = max(coprimes)
    for prime in range(max_val + 1, 10**5 + 1):
        if all(gcd(prime, c) == 1 for c in coprimes):
            return prime

    raise ValueError("No suitable coprime found")

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
