    a = list(map(int, data[1:n+1]))

    b = []
    coprimes = []
    exceeded = False

    for i in range(n):
        if not exceeded:
            # We haven't exceeded a yet
            v = find_next_coprime(a[i], coprimes)
            b.append(v)
            coprimes.append(v)
            exceeded = (v > a[i])
        else:
            # We've exceeded a, use the smallest coprime ≥ 2
            # Actually, we could use any value ≥ 2
            # But we want the smallest one that's coprime with all previous
            # So we find the smallest prime after max(coprimes)
            if not coprimes:
                v = 2
            else:
                v = find_next_coprime(2, coprimes)
            b.append(v)
            coprimes.append(v)

    print(' '.join(map(str, b)))

