import sys

def evaluate(expression):
    """Evaluate an expression with + and *"""
    if not expression:
        return 0

    # Handle single digit
    if expression[0].isdigit():
        return int(expression[0])

    # Standard evaluation with stack
    stack = []
    i = 0
    while i < len(expression):
        if expression[i].isdigit():
            num = int(expression[i])
            stack.append(num)
            i += 1
        else:
            # Handle operator
            if stack:
                right = stack.pop()
                left = stack.pop()
                if expression[i] == '+':
                    stack.append(left + right)
                else:
                    stack.append(left * right)
            else:
                # If stack is empty, we treat this as a prefix operator
                # Not valid for this problem, but we'll handle it as 0
                pass
            i += 1

    return stack[0] if stack else 0

# Solve function

def solve():
    expr = sys.stdin.read().strip()
    n = len(expr)
    max_result = 0

    # Try all possible bracket placements
    for i in range(n):
        for j in range(i + 1, n):
            # Extract left, middle, right parts
            left = expr[:i]
            middle = expr[i:j+1]
            right = expr[j+1:] if j+1 < n else ''

            # Evaluate left part with its rightmost operator
            if left:
                left_val = evaluate(left)
                left_op = left[-1]
            else:
                left_val = 0
                left_op = '+'

            # Evaluate middle part (this is what gets evaluated first)
            middle_val = evaluate(middle)

            # Evaluate right part with its leftmost operator
            if right:
                right_val = evaluate(right)
                right_op = right[0]
            else:
                right_val = 0
                right_op = '+'

            # Combine left, middle, and right
            left_middle = left_val + middle_val if left_op == '+' else left_val * middle_val
            total = left_middle + right_val if right_op == '+' else left_middle * right_val

            if total > max_result:
                max_result = total

    print(max_result)

if __name__ == "__main__":
    solve()
