from functools import lru_cache
import sys


def solve():
    n = int(sys.stdin.readline())
    p = tuple(map(int, sys.stdin.readline().split()))

    @lru_cache(maxsize=None)
    def dfs(state):
        if state == tuple(range(1, n+1)):
            return 0.0

        min_expected = float('inf')

        # Try all possible adjacent swaps
        for i in range(n - 1):
            # Make the swap
            new_state = list(state)
            new_state[i], new_state[i+1] = new_state[i+1], new_state[i]
            new_state = tuple(new_state)

            # After Jeff's move, it's Furik's turn
            expected = 1.0 + furik_move(new_state)
            min_expected = min(min_expected, expected)

        return min_expected

    def furik_move(state):
        if state == tuple(range(1, n+1)):
            return 0.0

        descents = []
        ascents = []

        for i in range(n - 1):
            if state[i] > state[i+1]:
                descents.append(i)
            elif state[i] < state[i+1]:
                ascents.append(i)

        if len(descents) + len(ascents) == 0:
            # No valid moves, Furik tosses again but nothing happens
            return 0.0

        expected = 0.0

        # Heads: pick a random descent
        if len(descents) > 0:
            prob_descents = 0.5 / len(descents)
            for i in descents:
                expected += dfs(tuple(list(state) + [state[i+1]] + [state[i]])) * prob_descents

        # Tails: pick a random ascent
        if len(ascents) > 0:
            prob_ascents = 0.5 / len(ascents)
            for i in ascents:
                expected += dfs(tuple(list(state) + [state[i+1]] + [state[i]])) * prob_ascents

        return expected

    result = dfs(p)
    print(f"{result:.6f}")

solve()
