import sys
from functools import lru_cache

def solve():
    q = int(sys.stdin.readline())
    for _ in range(q):
        b, l, r = map(int, sys.stdin.readline().split())

        def count_magic_numbers(n: int) -> int:
            # Convert n to base b
            digits = []
            temp = n
            while temp > 0:
                digits.append(temp % b)
                temp //= b

            # DP with memoization
            @lru_cache(maxsize=None)
            def dp(pos: int, tight: bool, mask: int, leading_zero: bool) -> int:
                if pos == len(digits):
                    # Check if all digits have even counts (mask == 0)
                    return 1 if mask == 0 else 0

                limit = digits[pos] if tight else b - 1
                total = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_mask = mask

                    if leading_zero:
                        # Still in leading zero mode
                        if d == 0:
                            # Continue leading zero mode, no digit added yet
                            new_leading_zero = True
                        else:
                            # Start of actual number, add this digit
                            new_leading_zero = False
                            new_mask ^= 1 << d
                    else:
                        # Already started the number, add this digit
                        new_leading_zero = False
                        new_mask ^= 1 << d

                    total += dp(pos + 1, new_tight, new_mask, new_leading_zero)

                return total

            return dp(0, True, 0, True)

        result = count_magic_numbers(r) - count_magic_numbers(l - 1)
        print(result)

if __name__ == "__main__":
    solve()
