import sys
from functools import lru_cache

def solve():
    q = int(sys.stdin.readline())
    for _ in range(q):
        b, l, r = map(int, sys.stdin.readline().split())

        def count_magic_numbers(n: int) -> int:
            # Convert n to base b
            digits = []
            temp = n
            while temp > 0:
                digits.append(temp % b)
                temp //= b

            if not digits:
                return 0

            # DP with memoization
            @lru_cache(maxsize=None)
            def dp(pos: int, tight: bool, leading_zero: bool, mask: int) -> int:
                if pos == len(digits):
                    # Check if mask has even counts for all digits
                    return 1 if mask == 0 else 0

                limit = digits[pos] if tight else b - 1
                total = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_leading_zero = leading_zero and (d == 0)

                    if leading_zero:
                        # Still in leading zero mode, not counting any digits
                        new_mask = mask
                    else:
                        # Count this digit
                        if d > 0:
                            # Already started counting, add to mask
                            new_mask = mask ^ (1 << d)
                        else:
                            # We just counted a zero now
                            new_mask = mask ^ (1 << 0)

                    # If we're still in leading zero mode and d > 0, we've started counting
                    new_started = not leading_zero

                    total += dp(pos + 1, new_tight, new_leading_zero, new_mask)

                return total

            # Start with leading zero mode
            return dp(0, True, True, 0)

        result = count_magic_numbers(r) - count_magic_numbers(l - 1)
        print(result)

if __name__ == "__main__":
    solve()

