import sys
from collections import deque

def bfs(start, end, graph, n):
    """Find the shortest path from start to end using BFS"""
    dist = [-1] * (n + 1)
    dist[start] = 0
    q = deque([start])

    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
                if v == end:
                    return dist
    return dist

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

