        graph = [[] for _ in range(n + 1)]
        for i in range(m):
            u = int(next(it))
            v = int(next(it))
            graph[u].append(v)
            graph[v].append(u)

        # Find shortest paths
        dist_ab = bfs(a, b, graph, n)
        dist_bc = bfs(b, c, graph, n)

        # Find common edges
