def count_palindrome_pairs(strings):
    from collections import Counter

    # Count strings by their odd character signature
    signature_counts = Counter()

    for s in strings:
        cnt = Counter(s)
        odd_chars = []
        for char, count in cnt.items():
            if count % 2 != 0:
                odd_chars.append(char)
        odd_chars.sort()
        signature = tuple(odd_chars)
        signature_counts[signature] += 1

    # Total pairs
    total_pairs = 0

    # Check all pairs
    signatures = list(signature_counts.keys())
    for i in range(len(signatures)):
        for j in range(i, len(signatures)):
            sig1 = signatures[i]
            sig2 = signatures[j]

            # Check if signatures are disjoint
            if not (set(sig1) & set(sig2)):
                # Disjoint signatures
                # Count of characters with odd parity in the combination
                combined_odds = set(sig1) | set(sig2)

                # If total length is even, all characters must be even
                if (len(sig1) + len(sig2)) % 2 == 0:
                    if len(combined_odds) == 0:
                        total_pairs += signature_counts[sig1] * signature_counts[sig2]
                else:
                    # Odd total length, exactly one character must be odd
                    if len(combined_odds) == 1:
                        total_pairs += signature_counts[sig1] * signature_counts[sig2]

    return total_pairs

