import sys

def solve():
    q = int(sys.stdin.readline())
    for _ in range(q):
        b, l, r = map(int, sys.stdin.readline().split())

        # Convert r to base b
        digits = []
        temp = r
        while temp > 0:
            digits.append(temp % b)
            temp //= b
        digits.reverse()

        # Digit DP to count numbers from 1 to r that are magic
        # State: position, mask, leading_zero, tight
        # mask: b-bit number where bit i is 1 if count of digit i is odd
        # leading_zero: 1 if we're still in leading zero state
        # tight: 1 if we're still tight to the original number

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, mask, leading_zero, tight):
            if pos == len(digits):
                # Check if all counts are even
                if leading_zero:
                    # If all zeros, count of 0 is even (0), other digits are 0
                    return 1
                # If not leading_zero, check mask
                return 1 if mask == 0 else 0

            limit = digits[pos] if tight else b - 1
            total = 0

            for d in range(0, limit + 1):
                new_mask = mask
                if d < b:
                    # Update mask (XOR)
                    new_mask ^= (1 << d)

                new_tight = tight and (d == limit)

                if leading_zero:
                    if d == 0:
                        # Still leading zeros
                        total += dp(pos + 1, new_mask, True, new_tight)
                    else:
                        # Exit leading zero state
                        total += dp(pos + 1, new_mask, False, new_tight)
                else:
                    # Already out of leading zero state
                    total += dp(pos + 1, new_mask, False, new_tight)

            return total

        count_r = dp(0, 0, True, True)

        # Convert l-1 to base b
        digits_l = []
        temp = l - 1
        while temp > 0:
            digits_l.append(temp % b)
            temp //= b
        digits_l.reverse()

        @lru_cache(maxsize=None)
        def dp_l(pos, mask, leading_zero, tight):
            if pos == len(digits_l):
                return 1

            limit = digits_l[pos] if tight else b - 1
            total = 0

            for d in range(0, limit + 1):
                new_mask = mask
                if d < b:
                    new_mask ^= (1 << d)

                new_tight = tight and (d == limit)

                if leading_zero:
                    if d == 0:
                        total += dp_l(pos + 1, new_mask, True, new_tight)
                    else:
                        total += dp_l(pos + 1, new_mask, False, new_tight)
                else:
