def is_adjacent(pos1, pos2):
    r1, c1 = pos1
    r2, c2 = pos2
    return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

def solve(s):
    n = len(s)
    if n != 27:
        return "Impossible"

    # Try placing the first letter at (0, 0)
    grid = [[None for _ in range(13)] for _ in range(2)]
    grid[0][0] = s[0]

    # Track which positions we've used
    used_positions = set([(0, 0)])

    # Track which letter appears twice
    letter_positions = {s[0]: [(0, 0)]}

    # Place subsequent letters
    for i in range(1, n):
        found = False
        for r in range(2):
            for c in range(13):
                if grid[r][c] is None and is_adjacent((0, 0), (r, c)):
                    grid[r][c] = s[i]
                    used_positions.add((r, c))

                    if s[i] in letter_positions:
                        letter_positions[s[i]].append((r, c))
                    else:
                        letter_positions[s[i]] = [(r, c)]

                    found = True
                    break
            if found:
                break

        if not found:
            return "Impossible"

    # Check if we've used all letters with one letter appearing twice
    if len(used_positions) != 26 or len(letter_positions) != 27:
        return "Impossible"

    # Check which letter appears twice
    double_letter = None
    for letter, positions in letter_positions.items():
        if len(positions) == 2:
            double_letter = letter
            break

    if double_letter is None:
        return "Impossible"

    # Check if the path is valid (each consecutive letters are adjacent)
    for i in range(n - 1):
        pos1 = None
        pos2 = None

        for r1, c1 in letter_positions[s[i]]:
            for r2, c2 in letter_positions[s[i+1]]:
                if is_adjacent((r1, c1), (r2, c2)):
                    pos1 = (r1, c1)
                    pos2 = (r2, c2)
                    break
            if pos1 is not None:
                break

        if pos1 is None:
            return "Impossible"

    # Output the grid
    row1 = ''.join(grid[0])
    row2 = ''.join(grid[1])

    # Ensure the second row has all letters
    while len(row1) < 13 or len(row2) < 13:
        row1 += ' ' * max(13 - len(row1), 1)
        row2 += ' ' * max(13 - len(row2), 1)

    return f"{row1}\n{row2}"}}

s = input().strip()
result = solve(s)
print(result)
