import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, k = int(data[0]), int(data[1])
    a = list(map(int, data[2:2+n]))

    min_ops = float('inf')
    best_a1 = 1

    # Calculate T_i = a_i - (i-1)*k for each i > 1
    targets = []
    for i in range(1, n+1):
        if i == 1:
            continue
        target = a[i-1] - (i-1)*k
        targets.append((i, target))

    # Try a_1 values around the median of targets
    if targets:
        # Find median target
        sorted_targets = sorted(targets, key=lambda x: x[1])
        median = sorted_targets[len(sorted_targets)//2][1]

        # Try a few values around the median
        for a1 in range(max(1, median - 50), median + 51):
            ops = 0
            for i, target in targets:
                ideal = a1 + (i-1)*k
                if a[i-1] != ideal:
                    ops += 1
            if ops < min_ops:
                min_ops = ops
                best_a1 = a1
    else:
        # No constraints except a_1 > 0
        best_a1 = 1

    # Now apply the operations
    result = []
    for i in range(1, n+1):
        ideal = best_a1 + (i-1)*k
        if a[i-1] == ideal:
            continue
        if a[i-1] < ideal:
            # Need to increase
            result.append(f"+ {i} {ideal - a[i-1]}")
        else:
            # Need to decrease
            result.append(f"- {i} {a[i-1] - ideal}")

    print(min_ops)
    for line in result:
        print(line)

if __name__ == "__main__":
    solve()
