        idx += 2

        a = list(map(int, data[idx:idx + n]))
        idx += n

        odd_count = sum(1 for num in a if num % 2 == 1)
        even_count = n - odd_count

        if even_count > 0:
            # We can mix odd and even elements
            if odd_count >= 1 and even_count >= x - 1:
