import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    N = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1

    capacities = []
    for _ in range(K):
        capacities.append(int(data[idx])); idx += 1

    # Find the best box type
    max_boxes = -1
    best_type = -1

    for i in range(K):
        a = capacities[i]

        # If N is 0, we can't transport any hamsters
        if N == 0:
            boxes = 0
        else:
            boxes = N // a

        # If we have a tie, prefer the earlier type
        if boxes > max_boxes:
            max_boxes = boxes
            best_type = i + 1  # 1-indexed
        elif boxes == max_boxes and best_type == -1:
            max_boxes = boxes
            best_type = i + 1

    print(f"{best_type} {max_boxes}")

if __name__ == "__main__":
    solve()
