def count_solutions(n, a, b, c, d):

    # Count valid (x, y) pairs where x + y = a + c and 1 <= x, y <= n
    target = a + c
    count = 0

    for x in range(1, n + 1):
        y = target - x
        if 1 <= y <= n:
            count += 1

    # For each valid x, check if w = b + x - c is valid
    valid_pairs = 0

    for x in range(1, n + 1):
        y = target - x
        if 1 <= y <= n:
            w = b + x - c
            if 1 <= w <= n:
