import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        grid = []
        for i in range(n):
            row = next(it)
            grid.append([int(c) for c in row])

        # We need to make all cells 0
        operations = []

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    # Select 3 cells in the 2x2 square that includes (i,j)
                    # Let's select: (i, j+1), (i+1, j+1), (i+1, j)
                    if i + 1 < n and j + 1 < m:
                        # Check if (i+1,j) and (i+1,j+1) are 1
                        if grid[i+1][j] == 0 and grid[i+1][j+1] == 0:
                            operations.append((i+1, j+1, i+1, j+2, i+2, j+1))
                            # This flips (i+1,j+1), (i+1,j+2), (i+2,j+1)
                            grid[i+1][j+1] ^= 1
                            grid[i+1][j+2] ^= 1
                            grid[i+2][j+1] ^= 1

        # Now handle remaining 1s in bottom row and rightmost column
        for j in range(m):
            if grid[n-1][j] == 1:
                # Flip bottom row using operation
                if j + 1 < m:
                    operations.append((n, j+1, n, j+2, n-1, j+1))
                    grid[n][j+1] ^= 1
                    grid[n][j+2] ^= 1
                    grid[n-1][j+1] ^= 1

        for i in range(n):
            if grid[i][m-1] == 1:
                # Flip rightmost column using operation
                if i + 1 < n:
                    operations.append((i+1, m, i+2, m, i+1, m-1))
                    grid[i+1][m] ^= 1
                    grid[i+1][m-1] ^= 1
                    grid[i+2][m-1] ^= 1

        out_lines.append(str(len(operations)))
        for op in operations:
            out_lines.append(' '.join(map(str, op)))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()

