import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def prime_factors(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = True
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = True
            n //= i
        i += 2
    if n > 1:
        factors[n] = True
    return factors

def solve():
    input = sys.stdin.read()
    data = input.split()

    n = int(data[0])
    idx = 1

    for _ in range(n):
        p = int(data[idx])
        q = int(data[idx+1])
        b = int(data[idx+2])
        idx += 3

        # Simplify fraction
        g = gcd(p, q)
        numerator = p // g
        denominator = q // g

        # If denominator is 1, it's finite
        if denominator == 1:
            print("Finite")
            continue

        # Check if all prime factors of denominator are also prime factors of b
        b_factors = prime_factors(b)

        # Check if denominator divides some power of b
        temp = denominator
        ok = True
        while temp > 1:
            # Find a prime factor of temp
            p = None
            for i in range(2, int(temp**0.5) + 1):
                if temp % i == 0:
                    p = i
                    break
            if p is None:
                p = temp  # temp is prime

            # Check if p divides b
            if p not in b_factors:
                ok = False
                break

            # Divide temp by p
            while temp % p == 0:
                temp //= p

        if ok:
            print("Finite")
        else:
            print("Infinite")

if __name__ == "__main__":
    solve()
"}

