def is_valid(freq):
    """Check if the frequency distribution is valid"""
    freq_values = list(freq.values())
    unique_freqs = list(set(freq_values))

    if len(unique_freqs) == 1:
        # All frequencies are the same
        return True
    elif len(unique_freqs) == 2:
        # Two different frequencies
        freq1, freq2 = unique_freqs
        if abs(freq1 - freq2) == 1:
            # Check if the larger frequency appears only once
            if freq1 > freq2:
                return freq1 in freq and freq.get(freq1) == 1
