import sys
from math import isqrt

def get_divisors(n):
    """Return divisors of n in increasing order"""
    divs = set()
    for i in range(1, isqrt(n) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(divs)

def solve():
    X, k = map(int, sys.stdin.readline().split())

    # If k is 0, return [X]
    if k == 0:
        print(X)
        return

    # Start with X0 = [X]
    current = [X]

    # Iterate up to k or until the sequence stabilizes
    for _ in range(k):
        # Generate next sequence by taking divisors of each element
        next_seq = []
        for num in current:
            next_seq.extend(get_divisors(num))

        # If next sequence is the same as current, we've stabilized
        if next_seq == current:
            break

        current = next_seq

        # If the sequence gets too long, we can stop early
        if len(current) > 100000:
            break

    # Output the first 100000 elements
    print(' '.join(map(str, current[:100000])))

if __name__ == "__main__":
    solve()
