def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    r = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Find positions of heaters (1-indexed)
    heaters = [i+1 for i, val in enumerate(a) if val == 1]

    if not heaters:
        print(-1)
        return

    position = 1
    count = 0

    while position <= n:
        # Find the furthest heater that can cover position
        furthest = -1
        for heater in heaters:
            if heater >= position:
                # Heater at position heater covers [heater - r + 1, heater + r - 1]
                if heater - r + 1 <= position <= heater + r - 1:
                    furthest = heater

        if furthest == -1:
            print(-1)
            return

        count += 1
        position = furthest + r

    print(count)

if __name__ == "__main__":
    solve()
