import sys
import math

def get_prime_factors(n):
    """Return a set of prime factors of n"""
    factors = set()
    while n % 2 == 0:
        factors.add(2)
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.add(i)
            n //= i
        i += 2
    if n > 1:
        factors.add(n)
    return factors

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    for _ in range(n):
        p = int(next(it))
        q = int(next(it))
        b = int(next(it))

        # Simplify the fraction
        g = math.gcd(p, q)
        p //= g
        q //= g

        if q == 1:
            print("Finite")
        else:
            # Check if all prime factors of q are also factors of b
            factors_q = get_prime_factors(q)
            factors_b = get_prime_factors(b)

            if factors_q.issubset(factors_b):
                print("Finite")
            else:
                print("Infinite")

if __name__ == "__main__":
    solve()
"}

