def count_calls(arr):
    """Count the number of mergesort calls for a given array."""
    def _count_calls(arr, l, r):
        # Check if the segment [l, r) is sorted
        is_sorted = True
        for i in range(l, r - 1):
            if arr[i] > arr[i + 1]:
                is_sorted = False
                break
        if is_sorted:
            return 1

        mid = (l + r) // 2
        # Count calls for left half
        left_calls = _count_calls(arr, l, mid)
        # Count calls for right half
        right_calls = _count_calls(arr, mid, r)
        # Merge step doesn't add calls
        return 1 + left_calls + right_calls

    return _count_calls(arr, 0, len(arr))

def construct_array(n, k):
    """Construct an array of size n with exactly k mergesort calls."""
    if n == 1:
        return [1] if k == 1 else -1

    if k == 1:
        return list(range(1, n + 1))

    max_calls = n * (n + 1) // 2
    if k > max_calls or k == 0:
        return -1

    # Try to find m such that left half of size m gives k_left calls
    # and right half gives k_right = k - 1 - k_left calls
    for m in range(1, n):
        # Left half size = m, right half size = n - m
        # Try all possible call distributions
        for k_left in range(1, 1 + m * (m + 1) // 2):
            k_right = k - 1 - k_left
            if k_right >= 1 and k_right <= (n - m) * (n - m + 1) // 2:
                # Construct left half with k_left calls
                left = recursive_construct(m, k_left)
                # Construct right half with k_right calls
                right = recursive_construct(n - m, k_right)
                return left + right

    return -1

def recursive_construct(n, k):
    """Recursively construct an array of size n with exactly k mergesort calls."""
    if n == 1:
        return [1] if k == 1 else -1

    if k == 1:
        return list(range(1, n + 1))

    max_calls = n * (n + 1) // 2
    if k > max_calls:
        return -1

    # Try to find the split point m
    for m in range(1, n):
        # Try all possible k_left values
        for k_left in range(1, 1 + m * (m + 1) // 2):
            k_right = k - 1 - k_left
            if k_right >= 1 and k_right <= (n - m) * (n - m + 1) // 2:
                # Recursively build both halves
                left = recursive_construct(m, k_left)
                right = recursive_construct(n - m, k_right)
                if left != -1 and right != -1:
                    # Combine the halves
                    # To avoid duplicates, we need to ensure unique values
                    # One approach: left half has values > n - m
                    # right half has values <= n - m
                    result = left + [val + (n - m) for val in right]
                    return result

    return -1

def solve():
    n, k = map(int, input().split())

    result = construct_array(n, k)

    if result == -1:
        print(-1)
    else:
        print(' '.join(map(str, result)))

