def get_divisors(n):
    """Return all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def min_moves_for_k(k):
    """Calculate minimum moves needed for target divisor k"""
    target = S // k
    moves = 0

    # For each box, calculate how many chocolates need to be moved
    for chocolates in a:
        if chocolates > target:
            moves += chocolates - target

    return moves // 2

# Find minimum moves over all valid divisors
min_moves = float('inf')
for divisor in get_divisors(S):
    if divisor > 1:
        moves = min_moves_for_k(divisor)
        min_moves = min(min_moves, moves)

