from itertools import permutations

def f1(p):  # Sum of absolute differences between adjacent elements
    return sum(abs(p[i] - p[i+1]) for i in range(len(p) - 1))

def f2(p):  # Sum of squares of differences between adjacent elements
    return sum((p[i] - p[i+1]) ** 2 for i in range(len(p) - 1))

def f3(p):  # Sum of absolute differences from the first element
    return sum(abs(p[0] - p[i]) for i in range(1, len(p)))

def f4(p):  # Sum of absolute differences from the last element
    return sum(abs(p[len(p)-1] - p[i]) for i in range(len(p)-1))

def f5(p):  # Sum of absolute differences from the middle element
    # Middle element index
    mid = len(p) // 2
    return sum(abs(p[mid] - p[i]) for i in range(len(p)))

def f6(p):  # Sum of absolute differences between all pairs
    return sum(abs(p[i] - p[j]) for i in range(len(p)) for j in range(i+1, len(p)))

def f7(p):  # Sum of absolute differences from the first and last elements
    return sum(abs(p[0] - p[i]) for i in range(1, len(p))) + sum(abs(p[len(p)-1] - p[i]) for i in range(len(p)-1))

def f8(p):  # Sum of absolute differences from the first and middle elements
    return sum(abs(p[0] - p[i]) for i in range(1, len(p))) + sum(abs(p[mid] - p[i]) for i in range(len(p)))

def f9(p):  # Sum of absolute differences from all three elements (for n=3)
    return abs(p[0] - p[1]) + abs(p[0] - p[2]) + abs(p[1] - p[2])

n, m = map(int, input().split())
