n = int(input())
nums = list(map(int, input().split()))

from collections import Counter

def solve():
    max_len = 0

    # Try all pairs as starting values
    for i in range(n):
        for j in range(n):
            if i == j:
                continue

            # Starting values
            a = nums[i]
            b = nums[j]

            # Check if we have at least 2 of the smaller value to potentially use multiple times
            count_a = Counter(nums)[a]
            count_b = Counter(nums)[b]

            # We need to be able to form the Fibonacci-ish sequence
            if (count_a >= 1 and count_b >= 1) or (a == b and count_a >= 2):
                # If a == b, we need at least 2 copies to use both as starting values
                if a == b:
                    if count_a < 2:
                        continue
                else:
                    if count_a < 1 or count_b < 1:
                        continue

                # Check if we can form the sequence
                seq = []
                if a == b:
                    seq = [a, b]
                    count_a -= 2
                else:
                    seq = [a, b]
                    count_a -= 1
                    count_b -= 1

                # If we only have one of the smaller value, we can't use it more than once
                max_reuse = 0
                if a == b:
                    pass
                elif count_a <= count_b:
                    max_reuse = count_a
                else:
                    max_reuse = count_b

                # Generate sequence
                while len(seq) < n and len(seq) < 1000:
                    a0 = seq[-2]
                    a1 = seq[-1]
                    next_val = a0 + a1

                    # If we have more copies of a or b, we might be able to use them
                    if count_a > 0 or count_b > 0 or count_a == count_b:
                        if next_val == a0:
                            if count_a > 0:
                                seq.append(next_val)
                                count_a -= 1
                            else:
                                break
                        elif next_val == a1:
                            if count_b > 0:
                                seq.append(next_val)
                                count_b -= 1
                            else:
                                break
                        elif next_val == a0 + a1:
                            # We need to check if we have this value
                            cnt = Counter(nums)[next_val]
                            if cnt > 0:
                                if cnt > count_a and cnt > count_b:
                                    cnt = min(count_a, count_b)
                                else:
                                    cnt = cnt - max_reuse

                                if cnt > 0:
                                    seq.append(next_val)
                                    count_a -= cnt
                                    count_b -= cnt
                                else:
                                    break
                            else:
                                break
                        else:
                            # This is a completely new value
                            if next_val in nums and nums.count(next_val) > 0:
                                seq.append(next_val)
                                nums.remove(next_val)
                            else:
                                break
                    else:
                        break

            max_len = max(max_len, len(seq))

    return max_len

print(solve())
