MOD = 998244353

def solve():
    n, k = map(int, input().split())

    # If k >= n, impossible
    if k >= n:
        print(0)
        return

    # If k == 0, just n! ways (permutation)
    if k == 0:
        ans = 1
        for i in range(1, n+1):
            ans = ans * i % MOD
        print(ans)
        return

    # If k > 0, use the formula: n! * (n-1)! / (n-k)! / k!
    ans = 1
    for i in range(1, n+1):
        ans = ans * i % MOD  # n!

    for i in range(1, n+1):
        ans = ans * i % MOD  # (n-1)! (but wait, we need to multiply n-1 terms...)

    # Actually, we need to multiply (n-1) terms
    for i in range(1, n):
        ans = ans * i % MOD

    # Divide by (n-k)!
    for i in range(1, n-k+1):
        ans = ans * pow(i, MOD-2, MOD) % MOD

    # Divide by k!
    for i in range(1, k+1):
        ans = ans * pow(i, MOD-2, MOD) % MOD

    print(ans)

solve()
"}

