import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
    K = int(data[1])

    capacities = list(map(int, data[2:2+K]))

    max_boxes = -1
    best_type = -1

    for i, capacity in enumerate(capacities):
        boxes = N // capacity

        if boxes > max_boxes:
            max_boxes = boxes
            best_type = i + 1  # 1-indexed

    print(f"{best_type} {max_boxes}")

if __name__ == "__main__":
    solve()
