    if double_letter in remaining:
        # We need to place the double letter twice
        # Place it at the beginning of row 1 and then later
        row1 = [''] * 13

        # Place the double letter at position 0 of row 1
        row1[0] = double_letter

        # Place the remaining letters in reverse order
        idx = 1
        for i in range(len(remaining) - 1, -1, -1):
            ch = remaining[i]
            if ch == double_letter and idx < 13:
                # We already placed the double letter
                idx += 1
                continue
            if idx < 13:
                row1[idx] = ch
                idx += 1
    else:
        # The double letter is only in the first part
        # Place the remaining letters in reverse order
        row1 = list(reversed(remaining))

    # Now check if the path exists through this grid

    # Build a map of positions for each letter
    pos_map = {}
    for i in range(13):
        if row0[i]:
            pos_map[row0[i]] = pos_map.get(row0[i], []) + [(0, i)]
        if row1[i]:
            pos_map[row1[i]] = pos_map.get(row1[i], []) + [(1, i)]

    # Try to find a path through the grid that spells s
    current_pos = None
    for i, ch in enumerate(s):
