def get_divisors(n):
    """Return sorted list of divisors of n."""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def apply_f(sequence):
    """Apply f to a sequence: divisors of each element in increasing order."""
    result = []
    for num in sequence:
        result.extend(get_divisors(num))
    return result

def compute_sequence(X, k, max_length=10**5):
    """Compute Xk using binary exponentiation."""
    def apply_k_times(seq, power):
        """Apply f power times to seq."""
        if power == 0:
            return seq[:max_length]
        if power % 2 == 1:
            # Apply once and then apply power//2 times
            seq = apply_f(seq)
            if len(seq) > max_length:
                seq = seq[:max_length]
            seq = apply_k_times(seq, power // 2)
        else:
            # Apply power//2 times and then power//2 times
            seq = apply_k_times(seq, power // 2)
            if len(seq) > max_length:
                seq = seq[:max_length]
            seq = apply_k_times(seq, power // 2)
        return seq

    result = apply_k_times([X], k)
    return result

