        return False
    if row == 1:
        return top_row[col - 1] == '.'
    else:
        return bottom_row[col - 1] == '.'

def bfs(start_row, start_col, target_row, target_col):
    # BFS to find shortest path from (start_row, start_col) to (target_row, target_col)
    # Return distance or -1 if unreachable

    # Queue: (row, col, distance)
    queue = [(start_row, start_col, 0)]
    visited = set()
    visited.add((start_row, start_col))

    while queue:
        row, col, dist = queue.pop(0)

        # Check if we reached the target
        if row == target_row and col == target_col:
            return dist

        # Check neighbors
        neighbors = []
        if is_empty(row, col + 1):
            neighbors.append((row, col + 1))
        if is_empty(row, col - 1):
            neighbors.append((row, col - 1))
        if is_empty(row + 1, col):
            neighbors.append((row + 1, col))
        if is_empty(row - 1, col):
            neighbors.append((row - 1, col))

        for neighbor in neighbors:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor[0], neighbor[1], dist + 1))

    return -1

for _ in range(m):
    v, u = map(int, input().split())

    # Convert to (row, col)
    row_v, col_v = to_row_col(v)
    row_u, col_u = to_row_col(u)

    print(bfs(row_v, col_v, row_u, col_u))

