def solve():
    MOD = 998244353
    n = int(input())
    ranges = []
    for _ in range(n):
        l, r = map(int, input().split())
        ranges.append((l, r))

    # DP[i][v] = number of ways for first i problems, with i-th having value v
    # We use a list of dictionaries for efficiency
    dp_prev = {}
    l1, r1 = ranges[0]
    for v in range(l1, r1 + 1):
        dp_prev[v] = 1

    for i in range(1, n):
        dp_curr = {}
        l_curr, r_curr = ranges[i]
        l_prev, r_prev = ranges[i-1]

        # For each possible value of current problem
        for v in range(l_curr, r_curr + 1):
            # Sum all valid previous values <= v
            total = 0
            for u in dp_prev:
                if u <= v:
                    total += dp_prev[u]
            dp_curr[v] = total

        dp_prev = dp_curr

    # Total combinations
    total = 1
    for l, r in ranges:
        total *= (r - l + 1)
        total %= MOD

    # Valid combinations
    valid = sum(dp_prev.values())

    # Probability = valid / total
    # Output = valid * modular_inverse(total) % MOD

    def modinv(x):
        """Fermat's little theorem: x^(MOD-2) mod MOD"""
        return pow(x, MOD - 2, MOD)

    result = valid * modinv(total) % MOD
    print(result)

