def solve():
    q = int(input())
    results = []

    for _ in range(q):
        b, l, r = map(int, input().split())

        # Convert n to base b
        def to_base(n):
            if n == 0:
                return [0]
            digits = []
            while n > 0:
                digits.append(n % b)
                n //= b
            digits.reverse()
            return digits

        # Count numbers <= n with exactly d_len digits that satisfy condition
        def count_exact(n, d_len):
            # First digit cannot be 0
            if d_len == 0:
                return 0

            memo = {}

            def dp(pos, mask, first_digit):
                if pos == d_len:
                    return 1 if mask == 0 and first_digit else 0

                key = (pos, mask, first_digit)
                if key in memo:
                    return memo[key]

                total = 0

                for d in range(0, b):
                    new_mask = mask
                    if d < b:
                        new_mask ^= (1 << d)

                    new_first = first_digit or (pos == 0 and d != 0)

                    # Skip if first digit and d == 0
                    if pos == 0 and d == 0:
                        continue

                    total += dp(pos + 1, new_mask, new_first)

                memo[key] = total
                return total

            if d_len % 2 == 1:
                return 0  # Must have even length

            return dp(0, 0, 0)

        # Count magic numbers <= n
        def count_magic(n):
            if n == 0:
                return 0

            digits = to_base(n)

            # Count numbers with exactly d_len digits
            result = 0
            for d_len in range(1, len(digits) + 1):
                if d_len % 2 == 1:
                    continue  # Must have even length

                result += count_exact(n, d_len)

            return result

        magic_r = count_magic(r)
        magic_l_minus_1 = count_magic(l - 1)
        results.append(magic_r - magic_l_minus_1)

    for res in results:
        print(res)

