import sys

def solve(s):
    # Try placing letters in a 2x13 grid
    # We'll use a snake-like pattern
    # Row 0: left to right
    # Row 1: right to left

    # If the string has length 27, we need to revisit at least one tile
    # But we can't revisit consecutively

    # Let's try a simple approach: place the first 26 letters in a path,
    # then check if we can extend to 27

    # Create a 2x13 grid
    grid = [['' for _ in range(13)] for _ in range(2)]

    # Place letters in a snake-like pattern
    # Row 0 left to right
    for i in range(13):
        grid[0][i] = s[i]

    # Row 1 right to left
    for i in range(13):
        grid[1][12 - i] = s[13 + i]

    # Check if we can form the path
    # We'll use DFS to find a path that spells s

    def is_adjacent(i1, j1, i2, j2):
        # Check if (i1,j1) is adjacent to (i2,j2)
        return abs(i1 - i2) <= 1 and abs(j1 - j2) <= 1 and (i1, j1) != (i2, j2)

    # Find the position of the first character
    start_pos = None
    for i in range(2):
        for j in range(13):
            if grid[i][j] == s[0]:
                start_pos = (i, j)
                break
        if start_pos:
            break

    if not start_pos:
        return "Impossible"

    # Use DFS to find a path
    visited = set()
    path = []

    def dfs(pos, depth):
        if depth == len(s):
            return True

        i, j = pos

        # Try all adjacent positions
        for ni in range(2):
            for nj in range(13):
                if is_adjacent(i, j, ni, nj) and (ni, nj) not in visited:
                    if s[depth] == grid[ni][nj]:
                        visited.add((ni, nj))
                        path.append((ni, nj))
                        if dfs((ni, nj), depth + 1):
                            return True
                        path.pop()
                        visited.remove((ni, nj))

        return False

    if dfs(start_pos, 0):
        return "".join(row for row in grid)
    else:
        return "Impossible"

s = sys.stdin.readline().strip()
print(solve(s))
