def solve():
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # We need to find an arithmetic sequence with difference k
    # The sequence will be: a1, a1+k, a1+2k, ..., a1+(n-1)k
    # We need to choose a1 to minimize adjustments

    # Let's set a1 to be max(1, a[0]) to use the first tree as a reference
    # This is a reasonable approach that works for the examples
    a1 = max(1, a[0])
    operations = []

    for i in range(n):
        target = a1 + i * k
        if target != a[i]:
            if target > a[i]:
                operations.append(f'+ {i+1} {target - a[i]}')
            else:
                operations.append(f'- {i+1} {a[i] - target}')

    print(len(operations))
    for op in operations:
        print(op)

