def matrix_mult(a, b, mod):
    """Matrix multiplication of two 3x3 matrices."""
    result = [[0] * 3 for _ in range(3)]
    for i in range(3):
        for k in range(3):
            if a[i][k] == 0:
                continue
            for j in range(3):
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
    return result

def matrix_pow(mat, power, mod):
    """Matrix exponentiation.
    Returns mat^power using binary exponentiation."""
    result = [[1 if i == j else 0 for j in range(3)] for i in range(3)]  # Identity matrix
    while power > 0:
        if power % 2 == 1:
            result = matrix_mult(result, mat, mod)
        mat = matrix_mult(mat, mat, mod)
        power //= 2
    return result

def apply_obstacles(mod, obstacles):
    """Create a transition matrix that accounts for obstacles.
    Returns a matrix where matrix[i][j] means ways to go from row i to row j in the next column."""
    mat = [[0] * 3 for _ in range(3)]
    mat[1][2] = 1  # From row 1 to row 2
    mat[2][0] = 1  # From row 2 to row 1
    mat[2][1] = 1  # From row 2 to itself
    mat[2][2] = 1  # From row 2 to row 2
    mat[0][2] = 1  # From row 3 to row 2

    # Adjust for obstacles
    for a, l, r in obstacles:
        for j in range(l, r + 1):
            if a == 1:
                mat[1][2] = 0  # Row 1 is blocked, so no transition from row 1 to row 2
            elif a == 3:
                mat[0][2] = 0  # Row 3 is blocked, so no transition from row 3 to row 2

    return mat

def solve(n, m, obstacles):
    mod = 10**9 + 7

    # Create transition matrix
    mat = apply_obstacles(mod, obstacles)

    # Base case: start at (2, 1)
    # ways = [ways_to_reach_row_1, ways_to_reach_row_2, ways_to_reach_row_3]
    ways = [0, 1, 0]

    # Apply transition matrix (m - 1) times
    mat_power = matrix_pow(mat, m - 1, mod)

    # Multiply base case with matrix power
    result = [0] * 3
    for i in range(3):
        for k in range(3):
            result[i] = (result[i] + ways[k] * mat_power[i][k]) % mod

    return result[1]  # We want ways to reach row 2 at column m

n, m = map(int, input().split())
obstacles = []
for _ in range(n):
    a, l, r = map(int, input().split())
    obstacles.append((a, l, r))

print(solve(n, m, obstacles))
