def is_tolerable(s):
    """Check if a string is tolerable (no palindrome substrings of length 2 or more)"""
    n = len(s)
    for i in range(n):
        # Check length-2 palindrome
        if i + 1 < n and s[i] == s[i + 1]:
            return False
        # Check length-3 palindrome
        if i + 2 < n and s[i] == s[i + 2]:
            return False
    return True

def find_next_tolerable(n, p, s):
    """Find the lexicographically next tolerable string"""
    # Convert string to list for easy modification
    chars = list(s)

    # Try to increment from the end
    for i in range(n - 1, -1, -1):
        # Get current character
        current_char = chars[i]

        # Try to increment to the next character
        for next_char in range(ord(current_char) + 1, ord('a') + p):
            # Check if this character creates a palindrome with neighbors
            valid = True

            # Check with left neighbor (if exists)
            if i > 0 and chars[i - 1] == chr(next_char):
                valid = False

            # Check with right neighbor (if exists)
            if i < n - 1 and chars[i + 1] == chr(next_char):
                valid = False

            # Check with character two positions away (if exists)
            if i > 1 and chars[i - 2] == chr(next_char):
                valid = False

            # Check with character three positions away (if exists)
            if i < n - 2 and chars[i + 2] == chr(next_char):
                valid = False

            if valid:
                # This character is valid, set it and fill rest with smallest valid characters
                chars[i] = chr(next_char)

                # Fill remaining positions with smallest valid characters
                for j in range(i + 1, n):
                    for candidate in range(ord('a'), ord('a') + p):
                        candidate_char = chr(candidate)

                        # Check if this character creates a palindrome with neighbors
                        valid_j = True

                        # Check with left neighbor (if exists)
                        if j > 0 and chars[j - 1] == candidate_char:
                            valid_j = False

                        # Check with right neighbor (if exists)
                        if j < n - 1 and chars[j + 1] == candidate_char:
