def evaluate(expression):
    """Evaluate a simple arithmetic expression with + and *"""

    # Split the expression into tokens
    tokens = []
    i = 0
    while i < len(expression):
        if expression[i].isdigit():
            tokens.append(int(expression[i]))
            i += 1
        else:
            tokens.append(expression[i])
            i += 1

    # Evaluate using stack approach
    stack = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if isinstance(token, int):
            stack.append(token)
        else:
            # Apply the operator to the top of stack
            if token == '+':
                stack[-1] = stack[-1] + stack.pop()
            else:  # '*'
                stack[-1] = stack[-1] * stack.pop()
        i += 1

    return stack[0]

def solve():
    expression = input().strip()

    max_value = 0
    n = len(expression)

    # Try all possible ways to add one pair of brackets
    for i in range(n):  # position of '(' (must be a digit)
        if i % 2 == 0 and expression[i].isdigit():
            for j in range(i+1, n):  # position of ')' (must be an operator)
                if j % 2 == 1 and expression[j] in {'+', '*'}:
                    # Create new expression with brackets
                    new_expr = expression[:i] + '(' + expression[i:j+1] + ')' + expression[j+1:]

                    # Evaluate the new expression
                    try:
                        value = evaluate(new_expr)
                        max_value = max(max_value, value)
                    except:
                        # Handle potential division by zero or other errors
                        pass

    print(max_value)

solve()
