def is_possible(a, max_xor):
    """Check if there exists an X such that for all i, a_i ⊕ X <= max_xor"""
    # For each bit position, decide whether to set it in X
    X = 0
    for bit in range(30, -1, -1):
        # Try setting this bit in X
        X_with_bit = X | (1 << bit)
        # Check if this would cause any XOR to exceed max_xor
        ok = True
        for num in a:
            if (num ^ X_with_bit) > max_xor:
                ok = False
                break

        if ok:
            # Setting this bit is okay, we can set it
            X = X_with_bit
        else:
            # Not setting this bit
            pass

    # Now check if the final X actually works
    for num in a:
        if (num ^ X) > max_xor:
            return False
    return True

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Binary search on the answer
    low = 0
    high = (1 << 30) - 1

    while low < high:
        mid = (low + high) // 2
        if is_possible(a, mid):
            high = mid
        else:
            low = mid + 1

    print(low)

solve()
