    p = list(map(int, input().split()))

    from collections import defaultdict

    # State is a tuple of the permutation
    # dp[state][whose_turn] = expected moves
    dp = defaultdict(lambda: [0.0, 0.0])  # [Jeff_turn, Furik_turn]

    def get_descents(state):
        d = 0
        for i in range(len(state) - 1):
            if state[i] > state[i+1]:
                d += 1
        return d

    def get_ascents(state):
        a = 0
        for i in range(len(state) - 1):
            if state[i] < state[i+1]:
                a += 1
        return a

    def get_neighbors(state):
        neighbors = []
        for i in range(len(state) - 1):
            new_state = list(state)
            new_state[i], new_state[i+1] = new_state[i+1], new_state[i]
            neighbors.append(tuple(new_state))
        return neighbors

    def compute_expected(state):
        # If sorted, expected moves is 0 for both
        if state == tuple(range(1, n+1)):
            dp[state][0] = 0.0
            dp[state][1] = 0.0
            return

        # If already computed, return
        if dp[state][0] != 0.0 or dp[state][1] != 0.0:
            return

        # Jeff's turn
        val = float('inf')
        for neighbor in get_neighbors(state):
            val = min(val, 1 + dp[neighbor][1])
        dp[state][0] = val

        # Furik's turn
        d = get_descents(state)
        a = get_ascents(state)

        if d == 0 and a == 0:
            # Furik tosses a coin repeatedly
            # Expected moves = 1 + 0.5*E + 0.5*E = 1 + E => E = 1
            dp[state][1] = 1.0
        else:
            # Furik makes a move
            descents = []
            ascents = []
            for i in range(len(state) - 1):
                if state[i] > state[i+1]:
                    new_state = list(state)
                    new_state[i], new_state[i+1] = new_state[i+1], new_state[i]
                    descents.append(tuple(new_state))
                elif state[i] < state[i+1]:
                    new_state = list(state)
                    new_state[i], new_state[i+1] = new_state[i+1], new_state[i]
                    ascents.append(tuple(new_state))

            if d == 0:
                expected = 1.0 + 1.0 * (sum(dp[n][0] for n in ascents) / a)
            elif a == 0:
                expected = 1.0 + 1.0 * (sum(dp[n][0] for n in descents) / d)
            else:
                expected = 1.0 + 0.5 * (sum(dp[n][0] for n in descents) / d) + 0.5 * (sum(dp[n][0] for n in ascents) / a)

            dp[state][1] = expected


    # Process states in reverse order of sort
    states = [tuple(range(1, n+1))]
    for k in range(1, n+1):
        for i in range(n - k):
            states.append(tuple([j for j in range(1, n+1) if j != i] + [i]))

    for state in sorted(states, key=lambda s: sum(s.count(j) for j in range(1, n+1))):  # Sort by number of inversions
        compute_expected(state)

    state = tuple(p)
    print(f"{dp[state][0]:.6f}")

