n, k = map(int, input().split())
a = list(map(int, input().split()))

# Try each position as pivot
min_changes = float('inf')
optimal_sequence = []

for pivot_idx in range(n):
    # Compute the target sequence starting from a[pivot_idx]
    target = []
    changes = 0
    valid = True

    for i in range(n):
        # Position i (0-indexed) in the sequence
        # Target height = a[pivot_idx] + (i - pivot_idx) * k
        # But we need to ensure it's positive

        if i < pivot_idx:
            # This is before the pivot, so we need to adjust it
            target_val = a[pivot_idx] - (pivot_idx - i) * k
        else:
            # This is at or after the pivot, so we need to adjust it
            target_val = a[pivot_idx] + (i - pivot_idx) * k

        if target_val <= 0:
            valid = False
            break

        target.append(target_val)
        if a[i] != target_val:
            changes += 1

    if valid and changes < min_changes:
        min_changes = changes
        optimal_sequence = target

# Output the result
print(min_changes)
for i in range(n):
    if a[i] != optimal_sequence[i]:
        if a[i] < optimal_sequence[i]:
            print(f"+ {i+1} {optimal_sequence[i] - a[i]}")
        else:
            print(f"- {i+1} {a[i] - optimal_sequence[i]}")
