from collections import defaultdict

freq = defaultdict(int)
for num in a:
    freq[num] += 1

missing = set()
for i in range(1, n + 1):
    if freq.get(i, 0) == 0:
        missing.add(i)

result = []
for num in a:
    if 1 <= num <= n and freq[num] == 1:
        # Keep this occurrence
        result.append(num)
        freq[num] = 0  # Mark as used
    else:
        # Replace with a missing number
        if missing:
            replace_with = missing.pop()
            result.append(replace_with)
        else:
            # This shouldn't happen
            result.append(num)

print(' '.join(map(str, result)))
